using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

[TestClass]
public sealed class EvalFixture
{
    private static DistributedApplicationTestingBuilder? _appHost;
    private static DistributedApplication? _app;
    private static ReportingConfiguration? _reportingConfiguration;

    public static IChatClient ChatClient { get; private set; } = null!;
    public static ReportingConfiguration ReportingConfiguration => _reportingConfiguration!;

    [AssemblyInitialize]
    public static async Task Initialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _appHost.Services.ConfigureHttpClientDefaults(b => b.AddStandardResilienceHandler());
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();

        ChatClient = _app.Services.GetRequiredService<IChatClient>();

        var storagePath = Path.Combine(
            Path.GetDirectoryName(typeof(EvalFixture).Assembly.Location)!,
            ".eval-results");

        _reportingConfiguration = new ReportingConfiguration(
            new DiskBasedResultStore(storagePath),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatConfiguration: new ChatConfiguration(ChatClient));
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }

        if (_appHost is not null)
        {
            await _appHost.DisposeAsync();
        }
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals;

[TestClass]
public sealed class ChatEvals
{
    [TestMethod]
    public async Task Chat_responds_coherently_to_greeting()
    {
        await using var scenario = await EvalFixture.ReportingConfiguration
            .CreateScenarioRunAsync(
                scenarioName: nameof(Chat_responds_coherently_to_greeting));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        var response = await EvalFixture.ChatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        // Verify basic response properties
        Assert.IsFalse(string.IsNullOrWhiteSpace(response.Text));
    }

    [TestMethod]
    public async Task Chat_follows_instructions_accurately()
    {
        await using var scenario = await EvalFixture.ReportingConfiguration
            .CreateScenarioRunAsync(
                scenarioName: nameof(Chat_follows_instructions_accurately));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant that responds concisely."),
            new(ChatRole.User, "List exactly 3 benefits of unit testing.")
        };

        var response = await EvalFixture.ChatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        Assert.IsFalse(string.IsNullOrWhiteSpace(response.Text));
    }

    [TestMethod]
    public async Task Chat_handles_multi_turn_conversation()
    {
        await using var scenario = await EvalFixture.ReportingConfiguration
            .CreateScenarioRunAsync(
                scenarioName: nameof(Chat_handles_multi_turn_conversation));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is dependency injection?")
        };

        var response1 = await EvalFixture.ChatClient.GetResponseAsync(messages);
        messages.Add(response1.Message);

        messages.Add(new ChatMessage(ChatRole.User, "Can you give me a simple example in C#?"));

        var response2 = await EvalFixture.ChatClient.GetResponseAsync(messages);
        messages.Add(response2.Message);

        await scenario.EvaluateAsync(messages);

        Assert.IsFalse(string.IsNullOrWhiteSpace(response2.Text));
    }
}

